    targets(table: Table, names: string[]): number[] {
        const seen = new Set<string>();
        return names.map((name) => {
            const index = table.columns.findIndex((c) => c.name === name);
            if (index < 0) fail("unknown column " + name);
            if (seen.has(name)) fail("duplicate column " + name);
